// payroll_profiles.js — generated by Generate Module

const { createApp } = Vue;

createApp({
  data() {
    return {
      systemName: SYSTEM_NAME,
      title:      '',
      loading: false,
      saving:  false,
      saved:   false,
      error:   '',
      isExisting: false,
      form: {
        ref: '',
      code: '',
      name: '',
      currency_ref: '',
      currency_name: '',
      pay_frequency: '',
      pay_day: 0,
      proration_method: '',
      fixed_divisor: 0,
      remarks: '',
      },
    };
  },

  computed: {
    isDirty() {
      return (
        this.form.code !== '' ||
        this.form.name !== '' ||
        this.form.currency_ref !== '' ||
        this.form.pay_frequency !== '' ||
        this.form.pay_day !== 0 ||
        this.form.proration_method !== '' ||
        this.form.fixed_divisor !== 0 ||
        this.form.remarks !== ''
      );
    },
  },

  mounted() {
    this.fetchRefNumber();
    document.addEventListener('payroll_profiles-selected', (e) => this.loadRecord(e.detail));
    document.addEventListener('pp-currency-selected', (e) => {
      this.form.currency_ref  = e.detail.ref;
      this.form.currency_name = e.detail.currency_name;
    });
  },

  methods: {
    fetchRefNumber() {
      this.loading = true;
      axios.get('/server/general/module_data.php?system_name=' + this.systemName)
        .then(res => { this.form.ref = res.data.ref; this.title = res.data.module; })
        .catch(err => { this.error = 'Failed to load reference number.'; console.error(err); })
        .finally(() => { this.loading = false; });
    },

    clearCurrency() { this.form.currency_ref = ''; this.form.currency_name = ''; },

    onAdd()    { this.onReset(); this.fetchRefNumber(); },
    onPrint() {
      if (!this.form.ref) { this.error = 'No record to print. Search and select a saved record first.'; return; }
      axios.get('/modules/human_resources_payroll/salary_setup/payroll_profiles/payroll_profiles_data.php?action=exists&ref=' + encodeURIComponent(this.form.ref))
        .then(res => {
          if (!res.data.exists) {
            this.error = 'No saved record found for this reference. Please search and select a record to print.';
            return;
          }
          const params = new URLSearchParams({
            ref: this.form.ref,
        code: String(this.form.code ?? ''),
        name: String(this.form.name ?? ''),
        currency_name: String(this.form.currency_name ?? ''),
        pay_frequency: String(this.form.pay_frequency ?? ''),
        pay_day: String(this.form.pay_day ?? ''),
        proration_method: String(this.form.proration_method ?? ''),
        fixed_divisor: String(this.form.fixed_divisor ?? ''),
        remarks: String(this.form.remarks ?? ''),
          });
          window.open('/modules/human_resources_payroll/salary_setup/payroll_profiles/payroll_profiles_print.php?' + params.toString(), '_blank');
        })
        .catch(err => { this.error = 'Failed to verify record.'; console.error(err); });
    },
    onCancel() { this.onReset(); },
    onClose()  { this.onReset(); },

    onReset() {
      this.saved = false;
      this.error = '';
      this.isExisting = false;
      this.form.code = '';
      this.form.name = '';
      this.form.currency_ref = '';
      this.form.currency_name = '';
      this.form.pay_frequency = '';
      this.form.pay_day = 0;
      this.form.proration_method = '';
      this.form.fixed_divisor = 0;
      this.form.remarks = '';
    },

    onSave() {
      if (!this.isDirty) return;
      this.saving = true;
      this.saved  = false;
      this.error  = '';

      const proceed = (action) => {
        axios.post('/modules/human_resources_payroll/salary_setup/payroll_profiles/payroll_profiles_data.php?action=' + action, this.form)
          .then(() => {
            this.saved = true;
            this.onReset();
            this.fetchRefNumber();
          })
          .catch(err => { this.error = 'Failed to save.'; console.error(err); })
          .finally(() => { this.saving = false; });
      };

      if (this.isExisting) {
        axios.get('/modules/human_resources_payroll/salary_setup/payroll_profiles/payroll_profiles_data.php?action=exists&ref=' + encodeURIComponent(this.form.ref))
          .then(res => {
            if (!res.data.exists) { this.error = 'Record not found. Please search again.'; this.saving = false; return; }
            proceed('update');
          })
          .catch(err => { this.error = 'Failed to verify record.'; console.error(err); this.saving = false; });
      } else {
        proceed('save');
      }
    },

    loadRecord(data) {
      this.form.ref = data.ref;
      this.form.code = data.code;
      this.form.name = data.name;
      this.form.currency_ref = data.currency_ref ?? '';
      this.form.currency_name = data.m_currencies?.currency_name ?? '';
      this.form.pay_frequency = data.pay_frequency;
      this.form.pay_day = data.pay_day;
      this.form.proration_method = data.proration_method;
      this.form.fixed_divisor = data.fixed_divisor;
      this.form.remarks = data.remarks;
      this.isExisting = true;
      this.saved = false;
      this.error = '';
    },
  },
}).mount('#payroll-profiles-app');